using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.Colors;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class UgoUpdate{
const string Work=@"C:\Users\user\Desktop\02_Справочники_CAD_Revit\odnolineyka\_Разработка\ugo";
public class Row{public string Title{get;set;}public string[] Handles{get;set;}public string Source{get;set;}public double Rotate{get;set;}}
static ObjectId Id(Database db,string h)=>db.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0);
static void Flatten(Entity e,List<Entity> result,HashSet<string> annotations,int depth=0){if(depth>8||!e.Visible||e is AttributeDefinition||e is AttributeReference){e.Dispose();return;}if(e is BlockReference){var children=new DBObjectCollection();e.Explode(children);e.Dispose();foreach(DBObject o in children){if(o is Entity c)Flatten(c,result,annotations,depth+1);else o.Dispose();}return;}if(e is DBText t&&annotations.Contains(t.TextString)){e.Dispose();return;}if(e is MText m&&annotations.Contains(m.Text)){e.Dispose();return;}result.Add(e);}
[CommandMethod("CODEXUGOUPDATEDRAFTV2",CommandFlags.Session)]public void Run(){try{
var rows=JsonSerializer.Deserialize<Row[]>(File.ReadAllText(Path.Combine(Work,"update_rows.json")));var target=JsonDocument.Parse(File.ReadAllText(Path.Combine(Work,"added.json"))).RootElement.GetProperty("File").GetString();var plans=AcApp.DocumentManager.Cast<Autodesk.AutoCAD.ApplicationServices.Document>().Single(d=>Path.GetFileName(d.Name).Equals("03_Чертежи ЭОМ_ХБК.dwg",StringComparison.OrdinalIgnoreCase));
using(var db=new Database(false,true)){db.ReadDwgFile(target,FileOpenMode.OpenForReadAndAllShare,true,null);db.CloseInput(true);var oldDb=HostApplicationServices.WorkingDatabase;try{HostApplicationServices.WorkingDatabase=db;ObjectId paperId,tableStyle;ObjectId[] oldLegend;using(var tr=db.TransactionManager.StartTransaction()){var ld=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);var lay=(Layout)tr.GetObject(ld.GetAt("УГО"),OpenMode.ForRead);paperId=lay.BlockTableRecordId;var paper=(BlockTableRecord)tr.GetObject(paperId,OpenMode.ForRead);oldLegend=paper.Cast<ObjectId>().Where(id=>id.Handle.ToString()!="2C3A4"&&tr.GetObject(id,OpenMode.ForRead) is not Viewport).ToArray();tableStyle=oldLegend.Select(id=>tr.GetObject(id,OpenMode.ForRead)).OfType<Table>().Single().TableStyle;}
var symbols=new List<(Row Row,List<Entity> Geometry)>();foreach(var row in rows){var geometry=new List<Entity>();var src=row.Source=="Plan"?plans.Database:db;var ids=new ObjectIdCollection(row.Handles.Select(h=>Id(src,h)).ToArray());var map=new IdMapping();if(src==db)db.DeepCloneObjects(ids,paperId,map,false);else src.WblockCloneObjects(ids,paperId,map,DuplicateRecordCloning.MangleName,false);
using(var tr=db.TransactionManager.StartTransaction()){foreach(ObjectId sid in ids){var e=(Entity)tr.GetObject(map[sid].Value,OpenMode.ForWrite);var annotations=new HashSet<string>();if(e is BlockReference br)foreach(ObjectId aid in br.AttributeCollection){var a=(AttributeReference)tr.GetObject(aid,OpenMode.ForWrite);if(a.Tag=="COUNT"){a.TextString="N";geometry.Add(new DBText{TextString="N",Height=a.Height,Position=a.Position,Rotation=a.Rotation,TextStyleId=a.TextStyleId,LayerId=a.LayerId});continue;}if(!string.IsNullOrWhiteSpace(a.TextString))annotations.Add(a.TextString);a.TextString="";a.Invisible=true;}Flatten((Entity)e.Clone(),geometry,annotations);e.Erase();}tr.Commit();}
if(geometry.Count==0)throw new System.Exception("Empty symbol: "+row.Title);if(row.Rotate!=0)foreach(var e in geometry)e.TransformBy(Matrix3d.Rotation(row.Rotate*Math.PI/180,Vector3d.ZAxis,Point3d.Origin));symbols.Add((row,geometry));}
var report=new List<object>();using(var tr=db.TransactionManager.StartTransaction()){var paper=(BlockTableRecord)tr.GetObject(paperId,OpenMode.ForWrite);foreach(var id in oldLegend)((Entity)tr.GetObject(id,OpenMode.ForWrite)).Erase();var table=new Table{TableStyle=tableStyle,Position=new Point3d(25,282,0),Layer="0"};table.SetSize(rows.Length+2,3);table.VerticalCellMargin=0.3;table.HorizontalCellMargin=0.5;table.SetRowHeight(4.5);table.Rows[0].Height=6;table.Rows[1].Height=6;table.Columns[0].Width=26;table.Columns[1].Width=114;table.Columns[2].Width=30;table.MergeCells(CellRange.Create(table,0,0,0,2));for(int r=0;r<table.Rows.Count;r++)for(int c=0;c<3;c++){table.Cells[r,c].TextHeight=2.3;table.Cells[r,c].Alignment=CellAlignment.MiddleLeft;table.Cells[r,c].ContentColor=Color.FromColorIndex(ColorMethod.ByAci,7);}table.Cells[0,0].TextString="Условные графические обозначения";table.Cells[0,0].Alignment=CellAlignment.MiddleCenter;table.Cells[1,0].TextString="Обозначение";table.Cells[1,1].TextString="Наименование";table.Cells[1,2].TextString="Примечание";for(int c=0;c<3;c++)table.Cells[1,c].Alignment=CellAlignment.MiddleCenter;for(int i=0;i<rows.Length;i++)table.Cells[i+2,1].TextString=rows[i].Title;table.GenerateLayout();paper.AppendEntity(table);tr.AddNewlyCreatedDBObject(table,true);
var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForWrite);for(int i=0;i<symbols.Count;i++){var s=symbols[i];Extents3d? ext=null;foreach(var e in s.Geometry){try{var x=e.GeometricExtents;if(ext==null)ext=x;else{var temp=ext.Value;temp.AddExtents(x);ext=temp;}}catch{}}if(ext==null)throw new System.Exception("No extents: "+s.Row.Title);var box=ext.Value;double w=Math.Max(box.MaxPoint.X-box.MinPoint.X,0.01),h=Math.Max(box.MaxPoint.Y-box.MinPoint.Y,0.01);double scale=Math.Min(20/w,3.3/h);var center=new Point3d((box.MinPoint.X+box.MaxPoint.X)/2,(box.MinPoint.Y+box.MaxPoint.Y)/2,0);var def=new BlockTableRecord{Name="CODEX_HBK_UGO_"+(i+1)};bt.Add(def);tr.AddNewlyCreatedDBObject(def,true);var transform=Matrix3d.Scaling(scale,Point3d.Origin)*Matrix3d.Displacement(Point3d.Origin-center);foreach(var e in s.Geometry){e.TransformBy(transform);e.LinetypeScale*=scale;e.Visible=true;var l=(LayerTableRecord)tr.GetObject(e.LayerId,OpenMode.ForWrite);l.IsOff=false;if(l.IsFrozen)l.IsFrozen=false;l.IsPlottable=true;def.AppendEntity(e);tr.AddNewlyCreatedDBObject(e,true);}var cell=new Point3dCollection();table.GetCellExtents(i+2,0,true,cell);double cx=cell.Cast<Point3d>().Average(p=>p.X),cy=cell.Cast<Point3d>().Average(p=>p.Y);var refb=new BlockReference(new Point3d(cx,cy,0),def.ObjectId){Layer="0"};paper.AppendEntity(refb);tr.AddNewlyCreatedDBObject(refb,true);report.Add(new{Index=i+1,s.Row.Title,s.Row.Source,s.Row.Handles,Parts=s.Geometry.Count,Width=w*scale,Height=h*scale});}var tx=table.GeometricExtents;if(tx.MinPoint.Y<90)throw new System.Exception("Table overlaps stamp; bottom="+tx.MinPoint.Y);tr.Commit();}
var draft=Path.Combine(Work,"УГО_ХБК_актуализированный.dwg");db.SaveAs(draft,DwgVersion.Current);File.WriteAllText(Path.Combine(Work,"update_draft.json"),JsonSerializer.Serialize(new{File=draft,Rows=report,Count=rows.Length,TableBottom=270-rows.Length*4.5,StampTop=85},new JsonSerializerOptions{WriteIndented=true}));}finally{HostApplicationServices.WorkingDatabase=oldDb;}}
}catch(System.Exception e){File.WriteAllText(Path.Combine(Work,"update_error.txt"),e.ToString());}}
}
